<script setup lang="ts">
import type { AppNotification } from '~~/shared/types/subscriptions'
const emit=defineEmits<{openEntry:[notification:AppNotification]}>()
const {store,open,settingsOpen,draft,showInbox,showSettings,save,addLead,removeLead,choose,stamp}=useNotificationCenter(n=>emit('openEntry',n))
</script>
<template>
 <div class="notification-controls"><button class="notification-bell" :aria-label="`Уведомления: ${store.unread} непрочитанных`" @click="showInbox"><UIcon name="i-lucide-bell"/><span v-if="store.unread" class="notification-count">{{store.unread>99?'99+':store.unread}}</span></button><button aria-label="Настройки уведомлений" title="Настройки уведомлений" @click="showSettings"><UIcon name="i-lucide-settings-2"/></button></div>
 <UModal v-model:open="open" title="Уведомления" description="Изменения общих хранилищ и напоминания о подписках."><template #body><div class="flex flex-wrap gap-2 mb-4"><UButton size="xs" color="neutral" variant="outline" label="Обновить" icon="i-lucide-refresh-cw" :loading="store.busy" @click="store.refresh()"/><UButton size="xs" variant="soft" label="Прочитать всё" :disabled="!store.unread" @click="store.markRead(store.items.filter(n=>!n.readAt).map(n=>n.id))"/><UButton size="xs" color="neutral" variant="ghost" label="Настройки" @click="showSettings"/></div><UAlert v-if="store.error" color="error" :description="store.error"/><p v-if="!store.items.length" class="text-sm text-slate-500 py-6">Новых уведомлений пока нет.</p><button v-for="item in store.items" :key="item.id" :class="['notification-item',{'is-unread':!item.readAt}]" @click="choose(item)"><strong>{{item.title}}</strong><p>{{item.message}}</p><small>{{stamp(item.createdAt)}}{{item.readAt?' · Прочитано':''}}</small></button><p class="mt-4 text-xs text-slate-400">Показаны последние доступные уведомления. На HTTP оповещения доступны внутри сайта при открытии и обновлении, без системных push-уведомлений.</p></template></UModal>
 <UModal v-model:open="settingsOpen" title="Настройки уведомлений" description="Настройки сохраняются для вашего аккаунта на всех устройствах."><template #body><form class="space-y-5" @submit.prevent="save"><UCheckbox v-model="draft.sharedChanges" label="Изменения общих хранилищ"/><UCheckbox v-model="draft.subscriptions" label="Напоминания о подписках"/><fieldset :disabled="!draft.subscriptions" class="space-y-4"><div><label class="text-sm font-medium">Напоминать за сколько дней до окончания</label><div v-for="(_,index) in draft.leadDays" :key="index" class="flex gap-2 mt-2"><UInput v-model.number="draft.leadDays[index]" type="number" :min="0" :max="3650" step="1" required aria-label="Число дней до окончания"/><UButton type="button" icon="i-lucide-x" aria-label="Удалить напоминание" color="neutral" variant="ghost" @click="removeLead(index)"/></div><UButton type="button" class="mt-3" variant="soft" size="xs" label="Добавить напоминание" :disabled="draft.leadDays.length>=12||!draft.subscriptions" @click="addLead"/><p class="mt-2 text-xs text-slate-500">0 — в день окончания. Можно задать несколько сроков.</p></div><UFormField label="Повторять каждые N дней"><UInput v-model.number="draft.repeatEveryDays" type="number" :min="0" :max="365" step="1" required/><p class="mt-2 text-xs text-slate-500">0 — без повторов. Отсчёт начинается с первого напоминания.</p></UFormField></fieldset><UAlert v-if="store.error" color="error" :description="store.error"/><UButton type="submit" label="Сохранить настройки" :loading="store.busy"/></form></template></UModal>
</template>
